/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/** Feeds every row of a cursor-paged listing to `visit`, page after page. */
async function forEachRow<T>(
  fetchPage: (
    cursor: string | null,
  ) => Promise<{ items: readonly T[]; nextCursor: string | null }>,
  visit: (row: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await fetchPage(cursor);
    for (const row of page.items) await visit(row);
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/**
 * Walks one tenant's live projects, non-archived issues and non-deleted
 * comments, page by page, and re-upserts every document; whatever else the
 * index holds for the org (deleted or archived content) is pruned afterwards.
 * Scoped to a single org on purpose: a full-fleet reindex is a sequence of
 * these, so one slow tenant cannot stall the rest.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const live = new Set<string>();

    await forEachRow(
      (cursor) => projectRepo.listProjects({ orgId, limit: PAGE_SIZE, cursor }),
      async (project) => {
        live.add(searchDocumentKey("project", project.id));
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachRow(
      (cursor) => issueRepo.listIssues({ orgId, limit: PAGE_SIZE, cursor }),
      async (issue) => {
        live.add(searchDocumentKey("issue", issue.id));
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachRow(
      (cursor) =>
        commentRepo.listLiveCommentsOfLiveIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
        }),
      async (comment) => {
        live.add(searchDocumentKey("comment", comment.id));
        try {
          await indexComment(orgId, comment);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index comment", {
            commentId: comment.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await pruneIndex(orgId, live);
  });
}
