cat > tests/server/zz-tmp-verify.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

const q = (orgId: any, kinds: any, s: string) =>
  searchRepo.searchDocuments({ orgId, q: s, kinds, limit: 100, cursor: null } as any);

describe("tmp", () => {
  it("works", async () => {
    const detach = searchService.registerSearchListeners();
    const t = await createTenant("tmpv", "growth");
    const o = await createTenant("tmpo", "growth");
    const a = t.actors.member;
    const i1 = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "I1 zed" }));
    const i2 = await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: "I2 zed" }));
    const oi = await issueService.createIssue(o.actors.member, issueInput(o.org.id, o.project.id, { title: "OI zed" }));
    const mk = (actor: any, org: any, issue: any, body: string, parentId: any = null) =>
      commentService.createComment(actor, { orgId: org, issueId: issue.id, body, parentId, mentionedUserIds: [] });
    const c1 = await mk(a, t.org.id, i1, "c1 zed");
    const r1 = await mk(a, t.org.id, i1, "r1 zed", c1.id);
    const c2 = await mk(a, t.org.id, i2, "c2 zed");
    const oc = await mk(o.actors.member, o.org.id, oi, "oc zed");
    expect((await commentRepo.countComments(t.org.id, i1.id))).toBe(2);
    await commentService.deleteComment(a, { orgId: t.org.id, commentId: c1.id });
    expect((await commentRepo.countComments(t.org.id, i1.id))).toBe(1);
    let r = await q(t.org.id, ["comment"], "zed");
    expect(r.items.map((x) => x.subjectId).sort()).toEqual([r1.id, c2.id].sort());
    await issueService.archiveIssue(a, t.org.id, i1.id);
    r = await q(t.org.id, ["comment", "issue", "project"], "zed");
    expect(r.items.map((x) => x.subjectId).sort()).toEqual([i2.id, c2.id].sort());
    expect((await q(o.org.id, ["comment", "issue"], "zed")).total).toBe(2);
    detach();

    // bulk
    for (let n = 0; n < 230; n++) {
      await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: `bulk ${n} zed` }) as any, t.userIds.member, 1000 + n);
    }
    const all = await issueRepo.listIssues({ orgId: t.org.id, limit: 100, cursor: null } as any);
    expect(all.total).toBe(231);
    for (let n = 0; n < 260; n++) {
      await commentRepo.insertComment({ orgId: t.org.id, issueId: i2.id, body: `long ${n} zed`, parentId: null, mentionedUserIds: [] } as any, t.userIds.member);
    }
    await commentRepo.insertComment({ orgId: t.org.id, issueId: i2.id, body: `orphan reply zed`, parentId: c1.id, mentionedUserIds: [] } as any, t.userIds.member);
    // stale doc
    await searchRepo.upsertSearchDocument(t.org.id, "comment", c1.id, "c1 zed", null);
    await runSearchReindexJob(t.org.id);
    const res = await runSearchReindexJob(t.org.id);
    expect(res.failed).toBe(0);
    const ir = await q(t.org.id, ["issue"], "zed");
    expect(ir.total).toBe(231);
    const cr = await q(t.org.id, ["comment"], "zed");
    expect(cr.total).toBe(1 + 260 + 1);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(1 + 231 + 262);
    expect((await q(o.org.id, ["comment", "issue"], "zed")).total).toBe(2);
    expect(oc.id).toBeTruthy();
  }, 60000);
});
EOF
